import {start,esc} from '../shared/runtime.js';
import {FACTS,MATERIALS,normalize} from '../shared/registry.js';
import {testCredential} from '../shared/credentials.js';
const app=document.querySelector('#app'),p=new URLSearchParams(location.search),file=p.get('file'),query=p.get('q')||'';let folder=p.get('folder')||MATERIALS[file]?.access||'public';
const {store,notebook,bindReading}=await start('pan');
const names={public:'与by共享的资料',editor:'禾声 / 第16期接收柜',sports:'摄影社 / 机位B原片袋'};
const files={dormLog:{name:'寝室记事_给by看的两页.txt',owner:'益达',size:'1.6 KB'},photoIndex:{name:'退回照片袋_F1018_目录.txt',owner:'飞星',size:'0.8 KB'},intake:{name:'第16期_接收清单.csv',owner:'飞星',size:'2.1 KB'},deleteRequest:{name:'F1018_删除请求.eml',owner:'益达',size:'1.2 KB'},handover:{name:'0321_设备交接场记.txt',owner:'阉鸡',size:'1.1 KB'}};
function content(id){switch(id){case 'dormLog':return `<div class="dorm-log" data-read="dormLog"><h2>寝室记事 · 只抄两段</h2><p>3月13日　杰哥去洗澡，先喊by给他拌面。乌鸡从隔壁来，说就尝一口。最后这“一口”大概有小半碗。我的汤放右边，饭团压在蓝本底下，谁也没发现。</p><p>3月19日　又有人要看去年那三张。我让飞星删F1018那组，不准拿来排校刊。by问是不是他那张医院的，我说你那是R0315，不是一个包。<del>这人记性真行</del></p><p>前面那次早上by蹲厕所没带纸，喊我。我已经走到楼梯了，真没听见。回来他说用花洒解决了。这个记录属实，后果自负。</p><p style="font-size:13px;color:#8d9cb0">其余页未提供。原本由益达保管。</p></div>`;
case 'photoIndex':return `<section class="letter-index" data-read="photoIndex"><h2>退回照片袋 / F1018</h2><p>原物：小信封一只。所有人：益达。形成日期：${FACTS.oldPhoto}。</p><div class="drive-scroller"><table class="index-table"><thead><tr><th>文件号</th><th>内容索引</th><th>处理</th></tr></thead><tbody><tr><td>F1018-01</td><td>信封正面</td><td>退回</td></tr><tr><td>F1018-02</td><td>信纸上半页</td><td>退回</td></tr><tr><td>F1018-03</td><td>信纸下半页</td><td>退回</td></tr></tbody></table></div><p>不含检验单。不提供信件预览。03月19日已按本人要求退回，收稿系统仅留目录。</p><p>登记：飞星　｜　接收柜单号：T0319-08</p></section>`;
case 'intake':return `<h2>禾声第16期 · 接收清单</h2><p class="drive-notice">按原始接收时间排列。预览去除个人联系方式，文件编号保留。接收并不表示采用。</p><div class="drive-scroller"><table class="intake-table" data-read="intake"><thead><tr>${['接收时间','来源','原始编号','项目','状态'].map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody><tr><td>03-19 18:21</td><td>益达</td><td>F1018-01..03</td><td>旧照片三张 / 10月18日</td><td>撤回；原物退回</td></tr><tr><td>03-19 18:26</td><td>by</td><td>R0315 / QH250315063</td><td>检验单去标识图 / DOB ${FACTS.dob}</td><td>保留原始接收件</td></tr><tr><td>03-21 16:08</td><td>待印目录</td><td>PRINT-0321-04</td><td>共享源图导出</td><td>导出完成；记录保留</td></tr><tr><td>03-23 20:16</td><td>匿名投稿</td><td>AN0323-02</td><td>日期03-14的报告图 / DOB ${FACTS.dob}</td><td>待核实；未作为新患者统计</td></tr><tr><td>03-23 20:19</td><td>编辑部</td><td>HS16-END</td><td>本期收稿截止</td><td>第17期仅选题预告</td></tr></tbody></table></div><p class="drive-version">导出者 飞星 · 2025-03-30 18:10 · 接收清单 r2（仅去标识，不改原始编号）</p>`;
case 'deleteRequest':return `<section class="message-envelope" data-read="deleteRequest"><h2>回复：退回照片袋</h2><dl><dt>发件人</dt><dd>益达</dd><br><dt>收件人</dt><dd>飞星</dd><br><dt>接收</dt><dd>2025-03-19 18:21</dd><br><dt>关联组</dt><dd><button class="redact" type="button" title="原始邮件字段；点击显示">F1018</button></dd></dl><p>那三张删掉吧，照片也别留备份。我周一来取信封。去年那事过了，别再往稿里放。</p><p>新传那张是by的，你别混着处理。我只撤F1018这组。</p><p class="drive-version">由本人同意向by提供此条相关请求。私人信件正文不在本次共享范围。</p></section>`;
case 'handover':return `<section class="letter-index" data-read="handover"><h2>0321 设备交接场记</h2><p>场地：看台后侧通道　机位B<br>拍摄记录：03-21 14:32、14:36（两次按快门，中间未连续拍摄）</p><p>14:31　朱贵、阉鸡一起把灰色打印机箱搬到通道。朱贵的旧外套左袖有黄色布贴。两人背对镜头。</p><p>14:36　箱子放在器材车旁，梁师傅到场点件。朱贵去打印室取电源线，阉鸡留在车旁。</p><p>登记：mj　交接签认：阉鸡<br>设备号：PR-04　去向：学生会临时打印点</p><p>设备点件完成。电源线归还后由值班人登记。</p></section>`;
default:return '<p>该文件不在本次共享范围。</p>';}}
function access(group){return `<form class="drive-code-form" data-unlock="${group}"><h2>${group==='editor'?'禾声共用阅览':'摄影社共享原片袋'}</h2><p>${group==='editor'?'本柜仅限本期去标识稿件。凭证格式在论坛的共用阅览说明中。':'请输入本次正片提取码。相册分享页按实拍月日与机位命名，不按上传日。'}</p><label>共享${group==='editor'?'凭证':'提取码'}<input name="code" autocomplete="off" required aria-describedby="code-error"></label><button>打开共享资料</button><p class="code-error" id="code-error" role="alert"></p><a href="${group==='editor'?'../index.html?thread=archive':'../video/index.html?view=register'}">${group==='editor'?'查看阅览说明':'查看拍摄登记'}</a></form>`;}
function render(){if(!Object.hasOwn(names,folder))folder='public';const requested=MATERIALS[file];const needed=requested?.access||(['editor','sports'].includes(folder)?folder:null);const allowed=!needed||store.get().accounts[needed]?.value;const exists=file&&Object.hasOwn(files,file);const title=exists?files[file].name:names[folder];let body;if(!allowed)body=access(needed);else if(exists)body=`<div class="drive-file-meta"><span>所有者 ${files[file].owner}</span><span>${files[file].size}</span><span>修改于 ${requested.recorded}</span><span>只读 · 保留原编号</span></div><div class="drive-preview">${content(file)}</div>`;else {const ids=Object.keys(files).filter(id=>(folder==='public'?!MATERIALS[id].access:MATERIALS[id].access===folder)&&(!query||files[id].name.includes(query)||MATERIALS[id].title.includes(query)));body=`<table class="drive-table"><thead><tr><th>文件名</th><th>修改时间</th><th>所有者</th><th>大小</th></tr></thead><tbody>${ids.map(id=>`<tr><td><span class="file-icon">▤</span><a href="index.html?file=${id}">${esc(files[id].name)}</a></td><td>${MATERIALS[id].recorded}</td><td>${files[id].owner}</td><td>${files[id].size}</td></tr>`).join('')||'<tr><td colspan="4">没有匹配文件。</td></tr>'}</tbody></table>`;}
app.innerHTML=`<p class="drive-path"><a href="index.html">共享空间</a> / <a href="index.html?folder=${folder}">${names[folder]}</a>${exists?' / '+esc(files[file].name):''}</p><div class="drive-tools"><h1>${esc(title)}</h1><small>${allowed?'原件只读':'共享范围受限'}　·　列表 / 预览</small></div>${body}`;bindReading(app);}
render();app.addEventListener('submit',async e=>{if(!e.target.matches('[data-unlock]'))return;e.preventDefault();const f=e.target,group=f.dataset.unlock;const result=testCredential(group,f.elements.code.value);if(!result.ok){const i=f.elements.code;i.classList.remove('shake');void i.offsetWidth;i.classList.add('shake','invalid');i.setAttribute('aria-invalid','true');f.querySelector('.code-error').textContent=result.message;return;}await store.update('accounts',group,true);notebook.feedback(result.message,{pulse:true});render();});
app.addEventListener('click',e=>{if(e.target.classList.contains('redact')){e.target.classList.toggle('revealed');e.target.setAttribute('aria-pressed',String(e.target.classList.contains('revealed')));}});store.subscribe((_s,m)=>{if(m.kind==='storage'&&app.querySelector('[data-unlock]'))render();});
